package com.ecopulse.service; import com.ecopulse.model.ConsumptionRecord; import com.ecopulse.repository.BuildingRepository; import com.ecopulse.repository.ConsumptionRepository; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.*; import java.util.*; @Service public class ImportService { private final BuildingRepository buildings; private final ConsumptionRepository repo; public ImportService(BuildingRepository b,ConsumptionRepository r){buildings=b;repo=r;} public Map<String,Integer> importCsv(Long org,MultipartFile file)throws IOException{ if(file.getSize()>5_000_000)throw new IllegalArgumentException("CSV exceeds 5 MB limit"); try(var br=new BufferedReader(new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8))){String header=br.readLine(); if(header==null||!header.toLowerCase().contains("timestamp")||!header.toLowerCase().contains("building"))throw new IllegalArgumentException("CSV must contain timestamp and building columns"); int received=0,ok=0,dup=0,bad=0; String line; while((line=br.readLine())!=null){if(line.isBlank())continue; received++; try{String[] p=line.split(",",-1); if(p.length<5)throw new IllegalArgumentException(); Instant ts=LocalDate.parse(p[0].trim()).atStartOfDay(ZoneOffset.UTC).toInstant(); if(ts.isAfter(Instant.now().plus(Duration.ofDays(1))))throw new IllegalArgumentException(); var b=buildings.findByOrganizationId(org).stream().filter(x->x.name.equalsIgnoreCase(p[1].trim())).findFirst().orElseThrow(); BigDecimal e=new BigDecimal(p[2]),w=new BigDecimal(p[3]),wa=new BigDecimal(p[4]); if(e.signum()<0||w.signum()<0||wa.signum()<0)throw new IllegalArgumentException(); String key=sha(org+"|"+b.id+"|"+ts+"|"+e+"|"+w+"|"+wa); ConsumptionRecord r=new ConsumptionRecord(); r.organizationId=org;r.buildingId=b.id;r.recordedAt=ts;r.electricityKwh=e;r.waterLiters=w;r.wasteKg=wa;r.costInr=e.multiply(BigDecimal.valueOf(8.5));r.co2Kg=e.multiply(BigDecimal.valueOf(.7));r.source="CSV";r.importKey=key; try{repo.save(r);ok++;}catch(Exception ex){dup++;}}catch(Exception ex){bad++;}} return Map.of("received",received,"imported",ok,"duplicates",dup,"invalid",bad); }} private String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
